import{_ as e,o as a,c as s,a2 as l}from"./chunks/framework.CHeM0PsO.js";const r=JSON.parse('{"title":"교육이수관리 교육알림 Push 기능 요약","description":"","frontmatter":{},"headers":[],"relativePath":"push-notification-summary.md","filePath":"push-notification-summary.md"}'),o={name:"push-notification-summary.md"};function t(p,i,d,c,n,h){return a(),s("div",null,[...i[0]||(i[0]=[l('<h1 id="교육이수관리-교육알림-push-기능-요약" tabindex="-1">교육이수관리 교육알림 Push 기능 요약 <a class="header-anchor" href="#교육이수관리-교육알림-push-기능-요약" aria-label="Permalink to &quot;교육이수관리 교육알림 Push 기능 요약&quot;">​</a></h1><h2 id="기능-개요" tabindex="-1">기능 개요 <a class="header-anchor" href="#기능-개요" aria-label="Permalink to &quot;기능 개요&quot;">​</a></h2><p><code>교육이수관리 &gt; 교육알림</code> 버튼은 안전교육을 아직 완료하지 않은 직원에게 Web Push 알림을 보내는 기능입니다.</p><p>관리자 화면에서 버튼을 누르면 현재 조회 대상 직원 중 미이수 교육이 1건 이상 있는 직원만 골라 서버 API로 전달하고, 서버는 Supabase에 저장된 각 직원의 푸시 구독 정보를 사용해 알림을 발송합니다.</p><h2 id="전체-흐름" tabindex="-1">전체 흐름 <a class="header-anchor" href="#전체-흐름" aria-label="Permalink to &quot;전체 흐름&quot;">​</a></h2><ol><li><p>관리자 화면에서 <code>교육알림</code> 버튼 클릭</p><ul><li>파일: <code>src/app/manager/safty/completions/page.tsx</code></li><li>현재 검색 결과의 재직 직원 중 <code>미이수 건수 &gt;= 1</code>인 사람만 발송 대상으로 선정합니다.</li><li>대상 목록을 <code>/api/notifications/send</code>로 POST 요청합니다.</li></ul></li><li><p>서버 API에서 푸시 발송</p><ul><li>파일: <code>src/app/api/notifications/send/route.ts</code></li><li>환경변수 <code>NEXT_PUBLIC_VAPID_PUBLIC_KEY</code>, <code>VAPID_PRIVATE_KEY</code>를 사용합니다.</li><li>Supabase <code>push_subscriptions</code> 테이블에서 대상 직원의 구독 정보를 조회합니다.</li><li><code>web-push</code> 라이브러리로 푸시 알림을 발송합니다.</li></ul></li><li><p>직원/경비원 쪽 푸시 구독 등록</p><ul><li>파일: <code>src/app/guard/main/guard-push-register.tsx</code></li><li>경비원 메인 화면 진입 시 sessionStorage에서 직원 ID를 읽습니다.</li><li>서비스워커를 등록하고 알림 권한을 요청합니다.</li><li>PushManager 구독 정보를 생성한 뒤 <code>/api/notifications/subscribe</code>로 저장 요청합니다.</li></ul></li><li><p>구독 정보 저장</p><ul><li>파일: <code>src/app/api/notifications/subscribe/route.ts</code></li><li><code>employee_id</code>, <code>endpoint</code>, <code>p256dh</code>, <code>auth</code>를 Supabase <code>push_subscriptions</code> 테이블에 upsert합니다.</li><li>동일 직원의 같은 endpoint는 중복 저장되지 않습니다.</li></ul></li><li><p>서비스워커에서 알림 수신/클릭 처리</p><ul><li>파일: <code>src/app/sw.ts</code></li><li>푸시 수신 시 알림을 표시합니다.</li><li>알림 클릭 시 <code>/guard/main</code>으로 이동합니다.</li><li>앱이 foreground 상태이면 서비스워커 메시지를 통해 화면 내 모달도 띄울 수 있습니다.</li></ul></li></ol><h2 id="supabase-테이블" tabindex="-1">Supabase 테이블 <a class="header-anchor" href="#supabase-테이블" aria-label="Permalink to &quot;Supabase 테이블&quot;">​</a></h2><p>관련 테이블은 <code>public.push_subscriptions</code>입니다.</p><p>주요 컬럼:</p><ul><li><code>id</code>: 구독 레코드 ID</li><li><code>employee_id</code>: 직원 ID</li><li><code>endpoint</code>: 브라우저 푸시 endpoint</li><li><code>p256dh</code>: Push 암호화 공개키</li><li><code>auth</code>: Push 인증 secret</li><li><code>created_at</code>: 생성 시각</li><li><code>updated_at</code>: 갱신 시각</li></ul><p>마이그레이션 파일:</p><ul><li><code>supabase/migrations/202605300001_create_push_subscriptions.sql</code></li></ul><p>현재 확인된 Supabase 상태:</p><ul><li><code>push_subscriptions</code> 테이블 존재</li><li>구독 데이터 1건 존재</li><li>등록 직원 수 1명</li></ul><h2 id="필요한-환경변수" tabindex="-1">필요한 환경변수 <a class="header-anchor" href="#필요한-환경변수" aria-label="Permalink to &quot;필요한 환경변수&quot;">​</a></h2><p><code>.env.local</code>에 아래 값이 필요합니다.</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NEXT_PUBLIC_VAPID_PUBLIC_KEY=생성된_Public_Key</span></span>\n<span class="line"><span>VAPID_PRIVATE_KEY=생성된_Private_Key</span></span></code></pre></div><p>VAPID 키 생성 명령:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web-push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> generate-vapid-keys</span></span></code></pre></div><p>주의:</p><ul><li><code>NEXT_PUBLIC_VAPID_PUBLIC_KEY</code>는 브라우저에 노출되는 공개키입니다.</li><li><code>VAPID_PRIVATE_KEY</code>는 서버 전용 비밀키이므로 GitHub에 커밋하면 안 됩니다.</li><li>환경변수를 추가하거나 수정한 뒤에는 Next.js 서버를 재시작해야 합니다.</li></ul><h2 id="로컬-테스트-시-주의사항" tabindex="-1">로컬 테스트 시 주의사항 <a class="header-anchor" href="#로컬-테스트-시-주의사항" aria-label="Permalink to &quot;로컬 테스트 시 주의사항&quot;">​</a></h2><p>현재 <code>next.config.ts</code> 설정에서 Serwist 서비스워커는 개발 모드에서 비활성화되어 있습니다.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">disable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: process.env.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">NODE_ENV</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ===</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;development&quot;</span></span></code></pre></div><p>따라서 <code>npm run dev</code> 상태에서는 <code>public/sw.js</code>가 생성되지 않아 새 브라우저/기기에서 푸시 구독 등록이 제대로 되지 않을 수 있습니다.</p><p>실제 푸시까지 검증하려면 다음 방식이 더 적합합니다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p>또는 개발 중에만 Serwist disable 조건을 임시로 조정해야 합니다.</p><h2 id="주요-에러와-원인" tabindex="-1">주요 에러와 원인 <a class="header-anchor" href="#주요-에러와-원인" aria-label="Permalink to &quot;주요 에러와 원인&quot;">​</a></h2><h3 id="vapid-키가-구성되지-않았습니다" tabindex="-1"><code>VAPID 키가 구성되지 않았습니다.</code> <a class="header-anchor" href="#vapid-키가-구성되지-않았습니다" aria-label="Permalink to &quot;`VAPID 키가 구성되지 않았습니다.`&quot;">​</a></h3><p>원인:</p><ul><li><code>NEXT_PUBLIC_VAPID_PUBLIC_KEY</code> 또는 <code>VAPID_PRIVATE_KEY</code>가 서버 실행 시점에 비어 있습니다.</li></ul><p>해결:</p><ul><li><code>.env.local</code>에 VAPID 키를 추가합니다.</li><li>Next.js 개발 서버를 재시작합니다.</li></ul><h3 id="알림-미수신-대상-기기-미등록" tabindex="-1"><code>알림 미수신 대상 - 기기 미등록</code> <a class="header-anchor" href="#알림-미수신-대상-기기-미등록" aria-label="Permalink to &quot;`알림 미수신 대상 - 기기 미등록`&quot;">​</a></h3><p>원인:</p><ul><li>해당 직원의 푸시 구독 정보가 Supabase <code>push_subscriptions</code>에 없습니다.</li><li>직원이 모바일/브라우저에서 경비원 메인 화면에 접속하지 않았거나 알림 권한을 허용하지 않았을 수 있습니다.</li></ul><p>해결:</p><ul><li>직원이 지원 브라우저에서 <code>/guard/main</code>에 접속합니다.</li><li>알림 권한을 허용합니다.</li><li>구독 정보가 <code>push_subscriptions</code>에 저장되는지 확인합니다.</li></ul><h3 id="전송-실패" tabindex="-1">전송 실패 <a class="header-anchor" href="#전송-실패" aria-label="Permalink to &quot;전송 실패&quot;">​</a></h3><p>원인:</p><ul><li>브라우저 endpoint 만료</li><li>기기 세션 만료</li><li>Push 서비스 네트워크 오류</li></ul><p>현재 구현:</p><ul><li>HTTP 404 또는 410 오류가 발생하면 만료된 endpoint로 판단하고 <code>push_subscriptions</code>에서 삭제합니다.</li></ul><h2 id="결론" tabindex="-1">결론 <a class="header-anchor" href="#결론" aria-label="Permalink to &quot;결론&quot;">​</a></h2><p>이 기능은 구조상 이미 구현되어 있습니다. 정상 동작을 위해 필요한 조건은 다음과 같습니다.</p><ol><li>VAPID 공개키/개인키가 환경변수에 설정되어 있어야 합니다.</li><li>Next.js 서버를 환경변수 반영 후 재시작해야 합니다.</li><li>직원/경비원 브라우저에서 푸시 구독 등록이 완료되어야 합니다.</li><li>로컬에서 실제 서비스워커까지 검증하려면 production 모드 실행이 필요합니다.</li></ol>',47)])])}const b=e(o,[["render",t]]);export{r as __pageData,b as default};
